local UIModule = CS.Engine.UI.UIModule
local TimeUtils = CS.Engine.Tools.TimeUtils

local ECSComponent = import("Frame.ECS.ECSComponent")
---@type MidFestivalHomeDojo
local MidFestivalHomeDojo = import("Game.Activity.MidFestival.Dojo.MidFestivalHomeDojo")
---@type MidFestivalTaskDojo
local MidFestivalTaskDojo = import("Game.Activity.MidFestival.Dojo.MidFestivalTaskDojo")
---@type MidFestivalMallDojo
local MidFestivalMallDojo = import("Game.Activity.MidFestival.Dojo.MidFestivalMallDojo")
---@type MidFestivalProductDojo
local MidFestivalProductDojo = import("Game.Activity.MidFestival.Dojo.MidFestivalProductDojo")

---@class ActivityMidFestivalComponent
local ActivityMidFestivalComponent = Class("ActivityMidFestivalComponent", ECSComponent)

local ActivityParamsDefine = {
    RESTORE_HP_INTERVAL  = 1, -- 恢复活动体力所需秒数
    RESTORE_NUM          = 2, -- 活动体力每次恢复X点
    HP_UP_LIMIT          = 3, -- 活动体力恢复上限
    BUY_CONSUME_ITEM     = 4, -- 兑换体力用道具id
    BUY_CONSUME_ITEM_NUM = 5, -- 消耗道具的数量（从左至右依次递增。到最右后循环）
    BUY_NUM              = 6, -- 消耗道具可兑换的体力数量
    BUY_DAILY_TIME_LIMIT = 7, -- 每日活动体力最多可兑换次数
}

function ActivityMidFestivalComponent:__init()
    self.name = "ActivityMidFestivalComponent"
    ---@type ActivityDojo
    self.activityDojo = nil
    ---@type MidFestivalHomeDojo
    self.homeDojo = MidFestivalHomeDojo.New()
    ---@type MidFestivalTaskDojo
    self.taskDojo = MidFestivalTaskDojo.New()
    ---@type MidFestivalMallDojo
    self.mallDojo = MidFestivalMallDojo.New()
    self.config = {
        PlaceId = {
            Boss = 3,
            Record = 2
        }
    }
end

function ActivityMidFestivalComponent:__delete()
    if self.homeDojo then
        self.homeDojo:RemoveTimer()
    end
end

--region public

function ActivityMidFestivalComponent:MainQuestStatus(id)
    local quest = self:GetHomeDojo().mainQuestHash[checkString(id)]
    if isNull(quest) then
        return 0
    end
    return quest.status
end

function ActivityMidFestivalComponent:HomeReq()
    GameUtils.Request(Interfaces.OverseaMidFestivalHome, {activityUuid = self.activityDojo.id}, function(request, response)
        if checkNumber(response.errCoder) ~= 0 then
            return
        end
        local jsonData = checkTable(response.data)
        self:GetHomeDojo():Fill(jsonData)
        Events.Broadcast(Constants.EventNames.MidFestivalHomeReq)
        Events.Broadcast(Constants.EventNames.EveryThingChangeEventName)
    end)
end

---@param taskId number @ 活动任务ID
function ActivityMidFestivalComponent:DrawTaskRewardReq(taskId)
    local req = {
        activityUuid = checkNumber(self.activityDojo.id),
        id = checkNumber(taskId),
        type = 1
    }
    GameUtils.Request(Interfaces.OverseaMidFestivalDrawTask, req, function(request, response)
        if checkNumber(response.errCoder) ~= 0 then
            return
        end
        local jsonData = response.data
        local rewards = checkTable(jsonData.rewards)
        if #rewards > 0 then
            GoodsUtils.DrawRewards(rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        Events.Broadcast(Constants.EventNames.ActivityMidFestivalDrawTaskRewardReq)
    end)
end

function ActivityMidFestivalComponent:UpdateMainQuestId(id)
    if checkNumber(id) == 0 then
        return
    end
    self.homeDojo.mainQuestId = id
    
    local allPlaceVos = CfUtils.GetCf(AutoIds.IdSetting6085, "MidFestivalMainQuestLocationVo", true)
    local activityDojo = self:GetActivityDojo()
    for i, v in pairs(allPlaceVos) do
        if v.activityId == activityDojo.activityContentId then
            if id >= checkNumber(v.unlockNum) then
                local quest = self.homeDojo.mainQuestHash[tostring(v.id)]
                if quest and quest.status == Constants.MidFestivalMapStatus.LOCK then
                    quest.status = Constants.MidFestivalMapStatus.NOW
                end
            end
        end
    end
end

function ActivityMidFestivalComponent:UpdateRepaintQuestId(id, status)
    if checkNumber(id) == 0 or isNull(self.homeDojo.repaintingQuestHash[checkString(id)]) then
        return
    end
    for _, v in ipairs(self.homeDojo.repaintingQuest) do
        if checkString(v.questId) == checkString(id) then
            v.status = status
            break
        end
    end
    self.homeDojo.repaintingQuestHash[checkString(id)].status = status
end

function ActivityMidFestivalComponent:BuyActivityHp()
    if not self:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local maxLimit = self:GetConfigParamsById(ActivityParamsDefine.HP_UP_LIMIT)
    local num = self:GetConfigParamsById(ActivityParamsDefine.BUY_NUM)
    local consumeGoodsId = self:GetConfigParamsById(ActivityParamsDefine.BUY_CONSUME_ITEM)
    local consumeGoodsNum = self:GetConfigParamsById(ActivityParamsDefine.BUY_CONSUME_ITEM_NUM)
    local homeDojo = self:GetHomeDojo()
    local buyTimes = checkInt(homeDojo.dailyBuyHpTimes)
    local maxBuyLimit = self:GetConfigParamsById(ActivityParamsDefine.BUY_DAILY_TIME_LIMIT)
    local maxBuyNum = 1
    if checkInt(buyTimes) >= checkInt(maxBuyLimit) then
        maxBuyNum = 0
    end
    local consumeNums = parse_strings(consumeGoodsNum)
    local consumeNum = consumeNums[buyTimes + 1] or consumeNums[#consumeNums]
    local prices = {{currency = checkInt(consumeGoodsId), current = checkInt(consumeNum)}}
    local activityTips = localize('今日剩余兑换次数: _num_', {_num_ = checkInt(maxBuyLimit) - buyTimes})
    local consume = {goodsId = consumeGoodsId, num = consumeNum}
    
    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = homeDojo.scheduleConf.energyId,
        goodsNum       = num,
        isShowNum      = true,
        maxHaveNum     = checkInt(maxLimit),
        prices         = prices,
        maxBuyNum      = maxBuyNum,
        activityTips   = activityTips,
        buyCb          = function (price, buyNum)
            GameUtils.Request(Interfaces.OverseaMidFestivalBuyHp, {consume = table.serialize(consume), activityUuid = self.activityDojo.id}, function(request, response)
                local showRewards = clone(response.data.rewards)
                table.insert(response.data.rewards, {
                    goodsId = consumeGoodsId,
                    num = -consumeNum
                })
                GoodsUtils.DrawRewards(response.data.rewards, true)
                homeDojo.hpData = checkTable(response.data.hpInfo)
                homeDojo.dailyBuyHpTimes = checkInt(homeDojo.dailyBuyHpTimes) + 1
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = showRewards } })
            end)
        end
    }})
end

---获取活动体力ID
function ActivityMidFestivalComponent:GetActivityEnergyId()
    if self.homeDojo and self.homeDojo.scheduleConf and self.homeDojo.scheduleConf.energyId then
        return self.homeDojo.scheduleConf.energyId
    end
    return Constants.Currency.MidFestivalStamina
end

---获取活动体力ID
function ActivityMidFestivalComponent:GetActivityCoinId()
    if self.homeDojo and self.homeDojo.scheduleConf and self.homeDojo.scheduleConf.cornId then
        return self.homeDojo.scheduleConf.cornId
    end
    return 9000013
end


---取得当前id 双旦活动参数表
function ActivityMidFestivalComponent:GetConfigParamsById(id)
    ---@type BaseArgVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6084, "MidFestivalActivityParameterVo", id)
    if vo == nil then
        printError("双旦活动参数表 中未找到 %s", id)
        return 0
    end
    return vo.num
end

