---IsActive @ 判断活动是否开启
function ActivityMidFestivalComponent:IsActive()
    if isNull(self.activityDojo) then
        return false
    end
    local startTime = checkNumber(self.activityDojo.startTime)
    local endTime = checkNumber(self.activityDojo.endTime)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curTime = comp:GetPlayerDojo():GetServerTimeWithTimeZone()
    return curTime >= startTime and curTime <= endTime
end

function ActivityMidFestivalComponent:IsBossUnlock()
    local unlockLevel = self:GetBossUnlockLevel()
    return checkBool(checkNumber(self.homeDojo.mainQuestId) >= checkNumber(unlockLevel))
end

