function ActivityMidFestivalComponent:AddActivityHp(value)
    local homeDojo = self:GetHomeDojo()
    if not homeDojo or not homeDojo.hpData then return end

    homeDojo.hpData.hp = checkInt(homeDojo.hpData.hp) + checkInt(value)
end

function ActivityMidFestivalComponent:GetActivityHp()
    local homeDojo = self:GetHomeDojo()
    if not homeDojo or not homeDojo.hpData then return end

    return checkInt(homeDojo.hpData.hp)
end

function ActivityMidFestivalComponent:GetMapUnlockName(mapId)
    ---@type MidFestivalMainQuestLocationVo
    local mapVo = CfUtils.GetCfVo(AutoIds.IdSetting6085, "MidFestivalMainQuestLocationVo", checkNumber(mapId))
    if checkNumber(mapVo.unlockNum) == 0 then
        return ""
    end
    ---@type MidFestivalMainQuestLevelVo
    local unlockVo = CfUtils.GetCfVo(AutoIds.IdSetting6086, "MidFestivalMainQuestLevelVo", checkNumber(mapVo.unlockNum))
    return unlockVo.name
end

function ActivityMidFestivalComponent:IsPassMainQuest(repaintQuestId)
    -- 判断复刷关卡ID对应的主线关卡是否已经解锁
    ---@type MidFestivalReChallengeLevelVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6079, "MidFestivalReChallengeLevelVo", checkNumber(repaintQuestId))
    if isNull(vo) then
        printError("未从双旦复刷关卡表中找到ID为" .. checkString(repaintQuestId) .. "的主键.")
        return
    end
    local targetMainUnlockId = checkNumber(vo.mainQuestUnlockLevel)
    local curMainId = checkNumber(self.homeDojo.mainQuestId)
    return curMainId >= targetMainUnlockId
end

function ActivityMidFestivalComponent:GetRankRewards()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting6102, "MidFestivalBossDamageRewardVo", true)
    local activityDojo = self:GetActivityDojo()
    local data = {}
    for i, v in pairs(allVos) do
        if v.activityId == activityDojo.activityContentId then
            table.insert(data,v)
        end
    end
    return data
end

